import{t as e}from"./utils-COoNfFoj.js";var t={slug:`kirsti-lang`,influencerName:`Kirsti Lang`,influencerHandle:`@KirstiLang`,influencerAvatarUrl:`${e}/kirsti-lang-avatar.jpeg`,heroDescription:`I have ADHD. I have no problem gathering tasks, but actually completing them is tough. I built Burrow to gather all my tasks in one calm space, help me prioritize them, and make completing them a little more fun.`,assetTitle:`Burrow`,screenshotUrl:`${e}/kirsti-lang.png`,remixUrl:`https://burrow.pplx.app/`,promptTitle:`Try Kirsti's Prompt`,promptText:`Create a clean, calming ADHD-friendly productivity dashboard UI with a Notion-like aesthetic. Use warm white or soft cream backgrounds, subtle gray dividers, very light borders, generous whitespace, rounded cards, and a minimal editorial feel. The layout should feel premium, quiet, and grown-up — not overly colorful, cluttered, or “gamer-y.” Prioritize clarity and emotional calm over density. The dashboard should have a left sidebar, a header, and a main content area. In the main area, place a hero card for the top task, a focus timer card beside it, a four-column task bucket section underneath (Quick wins, Deep work, Waiting on, Parking lot), and a simple progress/gamification card below. Use clean sans-serif typography, soft neutral surfaces, muted accent colors, subtle shadows, and spacing that makes the interface feel breathable and easy to scan. Avoid flashy SaaS gradients, neon colors, heavy illustration, loud gamification, or anything that looks like a startup template. Keep the visual language restrained, minimal, elegant, and productivity-first, like a thoughtfully designed personal dashboard for deep work. Make it feel like a cross between Notion, a modern editorial workspace, and a calm deep-work dashboard.`};export{t as default};
